[ "$E" = 0 ] || { echo "== eslint failed (see above); every step between it and here passed"; exit 1; }
echo '== full'; node_modules/.bin/vitest run --passWithNoTests --exclude tests/reviewer/runMutants.p22b.examples.test.ts --exclude tests/gate/gateMutants.examples.test.ts --exclude tests/gate/identity.examples.test.ts --exclude tests/gate/gateCommand.p22b.examples.test.ts --exclude tests/cli/gate.p22b.examples.test.ts --reporter=dot > $P/vt.log 2>&1 || { if grep -q '^ FAIL ' $P/vt.log; then awk '/^ FAIL /{p=1} p' $P/vt.log | grep -vE '^ +(Start at|Duration) ' | head -200; else tail -60 $P/vt.log; fi; node $P/firstdiff.mjs $P/vt.log; exit 1; }
echo '== own git'; G1=$( (git symbolic-ref -q HEAD || true; git rev-parse HEAD; git for-each-ref --format='%(refname) %(objectname)') 2>&1); [ "$G0" = "$G1" ] || { echo "tests changed this repository's HEAD or refs:"; echo "before: $G0" | head -5; echo "after: $G1" | head -5; exit 1; }
echo '== frozen'; git diff --quiet HEAD -- contour.yaml morph-map.json docs decks tests/fixtures templates || { echo "changed outside the targets: $(git diff --name-only HEAD -- contour.yaml morph-map.json docs decks tests/fixtures templates | tr "\n" " ")"; exit 1; }
X=$(git ls-files --others --exclude-standard | grep -vxF -e tests/reviewer/runMutants.p22b.examples.test.ts || true); [ -z "$X" ] || { echo "files left in the tree: $X"; exit 1; }
) > $L 2>&1; rc=$?; cat $L; exit $rc
